from causallearn.graph.GraphNode import GraphNode
from causallearn.graph.Endpoint import Endpoint


def _bdeu_local_score(X, node, parents, structure_prior=1.0, sample_prior=1.0):
    """Compute BDeu local score for a node given its parents."""
    from causallearn.score.LocalScoreFunction import local_score_BDeu
    return local_score_BDeu(X, node, parents, parameters={
        "sample_prior": sample_prior,
        "structure_prior": structure_prior,
    })


def run_causal_discovery(X: np.ndarray) -> GeneralGraph:
    """
    Hybrid Constraint-Score Algorithm (HCSA):
    1. Stability-selected skeleton via multi-alpha CI tests
    2. Score-based edge pruning with BDeu
    3. Greedy BDeu-guided edge orientation
    4. Meek completion
    """
    from causallearn.utils.PCUtils import SkeletonDiscovery, Meek
    from causallearn.utils.cit import CIT
    from causallearn.graph.GraphNode import GraphNode

    n_samples, n_vars = X.shape
    nodes = [GraphNode(f"X{i + 1}") for i in range(n_vars)]

    # Handle trivial cases
    if n_vars <= 1:
        return GeneralGraph(nodes)

    # ========== PHASE 1: Stability-selected skeleton ==========
    alphas = [0.001, 0.01, 0.05, 0.1]
    skeletons = {}

    for alpha in alphas:
        try:
            indep_test = CIT(X, "chisq")
            cg = SkeletonDiscovery.skeleton_discovery(
                X, alpha, indep_test, stable=True,
                background_knowledge=None, verbose=False,
                show_progress=False, node_names=None,
            )
            adj = np.zeros((n_vars, n_vars), dtype=bool)
            for i in range(n_vars):
                for j in range(n_vars):
                    if cg.G.is_adjacent_to(nodes[i], nodes[j]):
                        adj[i, j] = True
            skeletons[alpha] = adj
        except Exception:
            continue

    if not skeletons:
        return GeneralGraph(nodes)

    # Stability selection: edge must appear in multiple alpha levels
    alpha_weights = {0.001: 4.0, 0.01: 3.0, 0.05: 2.0, 0.1: 1.0}
    edge_support = np.zeros((n_vars, n_vars), dtype=float)

    for alpha, adj in skeletons.items():
        w = alpha_weights.get(alpha, 1.0)
        edge_support += adj.astype(float) * w

    skeleton = edge_support >= 2.5

    # ========== PHASE 2: Score-based edge pruning ==========
    for i in range(n_vars):
        current_parents = sorted(np.where(skeleton[:, i])[0].tolist())
        base_score = _bdeu_local_score(X, i, current_parents)

        for j in current_parents:
            reduced_parents = [p for p in current_parents if p != j]
            reduced_score = _bdeu_local_score(X, i, reduced_parents)
            reduced_score_j = _bdeu_local_score(X, j, 
                [p for p in sorted(np.where(skeleton[:, j])[0].tolist()) if p != i])
            base_score_j = _bdeu_local_score(X, j, 
                sorted(np.where(skeleton[:, j])[0].tolist()))

            if reduced_score > base_score - 0.5 and reduced_score_j > base_score_j - 0.5:
                skeleton[i, j] = False
                skeleton[j, i] = False

    # ========== PHASE 3: Greedy BDeu-guided edge orientation ==========
    adj = np.zeros((n_vars, n_vars), dtype=int)

    for i in range(n_vars):
        for j in range(i + 1, n_vars):
            if skeleton[i, j]:
                adj[i, j] = 1
                adj[j, i] = 1

    def has_directed_path(src, tgt, current_adj):
        visited = set()
        stack = [src]
        while stack:
            node = stack.pop()
            if node == tgt:
                return True
            if node in visited:
                continue
            visited.add(node)
            for c in np.where((current_adj[node, :] == 1) & 
                              (current_adj[:, node] == 0))[0]:
                if int(c) not in visited:
                    stack.append(int(c))
        return False

    def is_undirected(i, j, current_adj):
        return current_adj[i, j] == 1 and current_adj[j, i] == 1

    def is_directed(i, j, current_adj):
        return current_adj[i, j] == 1 and current_adj[j, i] == 0

    def get_parents(node, current_adj):
        return sorted(np.where((current_adj[:, node] == 1) & 
                               (current_adj[node, :] == 0))[0].tolist())

    improved = True
    max_iter = n_vars * n_vars
    iteration = 0

    while improved and iteration < max_iter:
        improved = False
        iteration += 1

        best_delta = -np.inf
        best_orientation = None

        current_total = 0.0
        cache = {}
        for i in range(n_vars):
            pa = get_parents(i, adj)
            key = (i, tuple(pa))
            cache[key] = _bdeu_local_score(X, i, pa)
            current_total += cache[key]

        for i in range(n_vars):
            for j in range(i + 1, n_vars):
                if not is_undirected(i, j, adj):
                    continue

                if not has_directed_path(j, i, adj):
                    pa_j_a = sorted(get_parents(j, adj) + [i])
                    key_a = (j, tuple(pa_j_a))
                    if key_a not in cache:
                        cache[key_a] = _bdeu_local_score(X, j, pa_j_a)
                    score_a = current_total - cache[(j, tuple(get_parents(j, adj)))] + cache[key_a]
                    delta_a = score_a - current_total
                else:
                    delta_a = -np.inf

                if not has_directed_path(i, j, adj):
                    pa_i_b = sorted(get_parents(i, adj) + [j])
                    key_b = (i, tuple(pa_i_b))
                    if key_b not in cache:
                        cache[key_b] = _bdeu_local_score(X, i, pa_i_b)
                    score_b = current_total - cache[(i, tuple(get_parents(i, adj)))] + cache[key_b]
                    delta_b = score_b - current_total
                else:
                    delta_b = -np.inf

                best_delta_local = max(delta_a, delta_b)
                if best_delta_local > best_delta + 1e-6:
                    best_delta = best_delta_local
                    if delta_a >= delta_b:
                        best_orientation = (i, j)
                    else:
                        best_orientation = (j, i)

        for i in range(n_vars):
            for j in range(n_vars):
                if i == j or not is_directed(j, i, adj):
                    continue
                pa_i_current = get_parents(i, adj)
                pa_i_new = sorted([p for p in pa_i_current if p != j])
                key_new = (i, tuple(pa_i_new))
                if key_new not in cache:
                    cache[key_new] = _bdeu_local_score(X, i, pa_i_new)
                delta = current_total - cache[(i, tuple(pa_i_current))] + cache[key_new]
                if delta > best_delta + 1e-6:
                    best_delta = delta
                    best_orientation = ("remove", j, i)

        if best_orientation is not None and best_delta > 0:
            if len(best_orientation) == 3 and best_orientation[0] == "remove":
                _, j, i = best_orientation
                adj[j, i] = 0
            else:
                src, tgt = best_orientation
                adj[src, tgt] = 1
                adj[tgt, src] = 0
            improved = True

    # ========== PHASE 4: Build graph and apply Meek rules ==========
    G = GeneralGraph(nodes)

    for i in range(n_vars):
        for j in range(n_vars):
            if i != j and adj[i, j] == 1 and adj[j, i] == 0:
                G.add_directed_edge(nodes[i], nodes[j])
            elif i < j and adj[i, j] == 1 and adj[j, i] == 1:
                G.add_undirected_edge(nodes[i], nodes[j])

    G = Meek.meek(G, background_knowledge=None)

    return G.G

