            for i in range(n_vars):
                for j in range(n_vars):
                    if cg.G.is_adjacent_to(nodes[i], nodes[j]):
                        adj[i, j] = True
            skeletons.append(adj)
        except Exception:
            continue

    if not skeletons:
        # Fallback: all pairs
        skeleton = np.ones((n_vars, n_vars), dtype=bool)
        np.fill_diagonal(skeleton, False)
    else:
        skeleton = np.zeros((n_vars, n_vars), dtype=bool)
        for adj in skeletons:
            skeleton |= adj

    # ========== PHASE 2: Greedy BDeu DAG construction ==========
    adj = np.zeros((n_vars, n_vars), dtype=int)  # 0=no edge, 1=i->j

    def has_directed_path(src, tgt, current_adj, n):
        visited = set()
        stack = [src]
        while stack:
            nd = stack.pop()
            if nd == tgt:
                return True
            if nd in visited:
                continue
            visited.add(nd)
            for c in range(n):
                if current_adj[nd, c] == 1 and c not in visited:
                    stack.append(c)
        return False

    def get_parents(node, current_adj):
        return sorted(np.where((current_adj[:, node] == 1) & 
                               (current_adj[node, :] == 0))[0].tolist())

    n = n_vars
    improved = True
    max_iter = n * n * 2
    iteration = 0

    while improved and iteration < max_iter:
        improved = False
        iteration += 1

        best_delta = -np.inf
        best_op = None

        # Recompute cache
        cache = {}
        for i in range(n):
            pa = get_parents(i, adj)
            key = (i, tuple(pa))
            cache[key] = bdeu_score(i, pa)

        # Try adding skeleton edges
        for i in range(n):
            for j in range(n):
                if i == j or adj[i, j] == 1:
                    continue
                if not skeleton[i, j]:
                    continue
                if has_directed_path(j, i, adj, n):
                    continue

                pa_j = get_parents(j, adj)
                pa_j_new = sorted(pa_j + [i])
                key_new = (j, tuple(pa_j_new))
                if key_new not in cache:
                    cache[key_new] = bdeu_score(j, pa_j_new)
                delta = cache[key_new] - cache[(j, tuple(pa_j))]

                if delta > best_delta + 1e-6:
                    best_delta = delta
                    best_op = ("add", i, j)

        # Try deleting edges
        for i in range(n):
            for j in range(n):
                if i == j or adj[i, j] != 1:
                    continue

                pa_j = get_parents(j, adj)
                pa_j_new = sorted([p for p in pa_j if p != i])
                key_new = (j, tuple(pa_j_new))
                if key_new not in cache:
                    cache[key_new] = bdeu_score(j, pa_j_new)
                delta = cache[key_new] - cache[(j, tuple(pa_j))]

                if delta > best_delta + 1e-6:
                    best_delta = delta
                    best_op = ("delete", i, j)

                # Try reversing i->j to j->i
                if not has_directed_path(i, j, adj, n):
                    pa_i = get_parents(i, adj)
                    pa_i_new = sorted(pa_i + [j])
                    key_new_i = (i, tuple(pa_i_new))
                    if key_new_i not in cache:
                        cache[key_new_i] = bdeu_score(i, pa_i_new)

                    delta_rev = (cache[(j, tuple(pa_j_new))] - cache[(j, tuple(pa_j))] +
                                 cache[key_new_i] - cache[(i, tuple(pa_i))])

                    if delta_rev > best_delta + 1e-6:
                        best_delta = delta_rev
                        best_op = ("reverse", i, j)

        if best_op is not None and best_delta > 0:
            op_type, i, j = best_op
            if op_type == "add":
                adj[i, j] = 1
            elif op_type == "delete":
                adj[i, j] = 0
            elif op_type == "reverse":
                adj[i, j] = 0
                adj[j, i] = 1
            improved = True

    # ========== PHASE 3: Convert DAG to CPDAG ==========
    G = GeneralGraph(nodes)
    for i in range(n):
        for j in range(n):
            if adj[i, j] == 1:
                G.add_directed_edge(nodes[i], nodes[j])

    G = dag2cpdag(G)

    return G
